"""Publish the verified guided learning walkthrough with chapters and capture evidence."""
from pathlib import Path
import json,html,hashlib,shutil
R=Path(__file__).resolve().parents[1];N='managed-agents-guided-learning-walkthrough';P=R/'presentations'/N;V=R/'videos'/N
TITLE='Guided Learning Walkthrough: Study, Practice, and Track Your Progress'
r=json.loads((V/'validation.json').read_text(encoding='utf-8'));assert r['fullVideoAndAudioDecode']=='passed';assert hashlib.sha256((V/r['file']).read_bytes()).hexdigest()==r['sha256']
t=json.loads((V/'timeline.json').read_text(encoding='utf-8'));story=json.loads((P/'storyboard.json').read_text(encoding='utf-8'));e=json.loads((V/'walkthrough-evidence.json').read_text(encoding='utf-8'))
assert len(t['slides'])==len(story)==20 and not e['errors'] and not e['liveExecution']
shutil.copy2(P/'.build/video/slides/slide-01.png',V/'cover.png')
chapters=[]
for row,s in zip(t['slides'],story):
 sec=int(row['start']);chapters.append(f'<li><button data-start="{row["start"]}" onclick="const v=document.querySelector(\'video\');v.currentTime=Number(this.dataset.start);v.play()">{sec//60}:{sec%60:02} · {html.escape(s["title"])}</button></li>')
page=(V/'index.html').read_text(encoding='utf-8').replace('poster="highlight-preview.jpg"','poster="cover.png"')
extra='<section><h2>Lesson chapters</h2><ol style="columns:2;line-height:2">'+''.join(chapters)+f'</ol><p>{len(e["shots"])} application views were captured with Playwright from the running learning platform in a fresh browser profile. The only exercise run used an authored offline fixture; no live provider session was created. Learning state shown on screen (answers, note, bookmark, checklists and path) was created during the capture.</p><p><a href="walkthrough-evidence.json">Capture evidence</a> · <a href="narration-script.txt">Narration script</a> · <a href="geometry-audit.json">Highlight geometry</a></p></section><style>button{{background:none;border:0;color:#f2b48f;font:inherit;text-align:left;cursor:pointer}}li{{break-inside:avoid}}@media(max-width:750px){{ol{{columns:1!important}}}}</style>'
if 'Lesson chapters' not in page:page=page.replace('</main>',extra+'</main>')
(V/'index.html').write_text(page,encoding='utf-8');sec=int(r['durationSeconds']);stamp=f'{sec//60}:{sec%60:02}'
catalog=R/'videos/index.html';body=catalog.read_text(encoding='utf-8');card=f'<article data-project="{N}"><span>CLAUDE MANAGED AGENTS · GUIDED LEARNING WALKTHROUGH</span><a href="{N}/index.html"><img loading="lazy" src="{N}/cover.png" alt="{html.escape(TITLE)}"></a><div><h2>{html.escape(TITLE)}</h2><p>Verified · {stamp} · 1080p · Yash narration · {len(e["shots"])} real application views</p><a href="{N}/{r["file"]}">MP4</a> · <a href="{N}/index.html">Player and chapters</a></div></article>'
if f'data-project="{N}"' not in body:catalog.write_text(body.replace('<main>','<main>'+card,1),encoding='utf-8')
(V/'README.txt').write_text(f'CLAUDE MANAGED AGENTS: {TITLE.upper()}\nDuration: {stamp}. 1920x1080, 30 fps, H.264/AAC. Inworld Yash, TTS 2, enhanced, balanced delivery, speaking rate 1.25, 48kHz.\n\n20 scenes: cover; study/practice/track overview; lesson entry points; Learning Guide; narrated tour; concept map tour; lab walkthrough tour; narrated TypeScript source; full-screen code reader; offline exercise; incorrect knowledge answer; correct knowledge answer; notebook and bookmark; checklist; course progress; learning paths; review queue; milestone projects; learning backup; closing routine.\n\nAll application views were captured with Playwright from the running platform (npm run dev) in a fresh browser profile. One Normal turn offline fixture was run; no live provider session was created. Backup restore was not performed.\n\nRebuild (with npm run dev running): node scripts/capture-guided-learning-walkthrough.mjs; python scripts/create-guided-learning-walkthrough.py; node scripts/capture-guided-learning-walkthrough-slides.mjs; python scripts/create-guided-learning-walkthrough.py; python scripts/audit-guided-learning-walkthrough.py; python -u scripts/build-narrated-presentation.py --project {N}; python scripts/finish-guided-learning-walkthrough.py\n',encoding='utf-8')
print(f'Guided learning walkthrough player ready: {stamp}, {len(chapters)} chapters.')
